import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { ordersMock, orderLinesMock } from '../../mocks/orders.mock.ts';
import { restaurantsMock } from '../../mocks/restaurants.mock.ts';
import {
  customerProfilesMock,
  customersMock,
  couriersMock,
} from '../../mocks/users.mock.ts';
import {
  applyRestaurantStatus,
  availableStatusChanges,
  calculateOrderTotal,
  canOperatorCancel,
  countActiveOrders,
  countOpenRestaurants,
  formatRegisteredSummary,
  getCustomerBalance,
  getOperatorDisplayName,
  markOrderCancelled,
  profileFromResponse,
  toOperatorUser,
  validateProfileUpdate,
} from '../../app/operator/operatorLogic.ts';

describe('operator dashboard - counts', () => {
  it('counts only open restaurants', () => {
    assert.equal(countOpenRestaurants(restaurantsMock), 2);
    assert.equal(countOpenRestaurants([]), 0);
  });

  it('counts placed/accepted/preparing/ready/picked_up as active orders', () => {
    // mock: preparing + placed are active; rejected, cancelled, delivered are not
    assert.equal(countActiveOrders(ordersMock), 2);
  });

  it('treats an empty order list as zero active orders', () => {
    assert.equal(countActiveOrders([]), 0);
  });

  it('only lists customers and couriers in their own stat cards', () => {
    assert.ok(customersMock.every((u) => u.role === 'customer'));
    assert.ok(couriersMock.every((u) => u.role === 'courier'));
  });
});

describe('operator dashboard - order totals', () => {
  it('sums quantity * unit price across the lines of one order', () => {
    assert.equal(calculateOrderTotal(9001, orderLinesMock), '20.75');
    assert.equal(calculateOrderTotal(9002, orderLinesMock), '31.50');
  });

  it('returns 0.00 for an order with no lines', () => {
    assert.equal(calculateOrderTotal(123456, orderLinesMock), '0.00');
  });
});

describe('operator dashboard - customer balance', () => {
  it('formats the TD Cash balance with two decimals', () => {
    assert.equal(getCustomerBalance(1, customerProfilesMock), '25.00');
    assert.equal(getCustomerBalance(2, customerProfilesMock), '8.50');
  });

  it('falls back to 0.00 when the customer has no profile', () => {
    assert.equal(getCustomerBalance(999, customerProfilesMock), '0.00');
  });
});

describe('operator dashboard - summary text', () => {
  it('uses the singular for exactly one', () => {
    assert.equal(formatRegisteredSummary(1, 'Courier'), '1 Registered Courier');
  });

  it('uses the plural for zero or many', () => {
    assert.equal(formatRegisteredSummary(0, 'Courier'), '0 Registered Couriers');
    assert.equal(formatRegisteredSummary(3, 'Customer'), '3 Registered Customers');
  });
});

describe('operator dashboard - signed-in operator', () => {
  const operatorAuth = {
    id: 42,
    role: 'Operator' as const,
    name: 'Olivia Operator',
    email: 'operator@demo.test',
    phoneNumber: '+15145550108',
  };

  it('maps the signed-in Operator account to the profile shown in the modal', () => {
    assert.deepEqual(toOperatorUser(operatorAuth), {
      id: 42,
      name: 'Olivia Operator',
      email: 'operator@demo.test',
      phone: '+15145550108',
      role: 'operator',
    });
  });

  it('returns undefined for non-operators or no session', () => {
    assert.equal(toOperatorUser({ ...operatorAuth, role: 'customer' }), undefined);
    assert.equal(toOperatorUser(null), undefined);
  });

  it('shows the operator name, or "Operator" as a fallback', () => {
    assert.equal(getOperatorDisplayName(toOperatorUser(operatorAuth)), 'Olivia Operator');
    assert.equal(getOperatorDisplayName(undefined), 'Operator');
  });
});

describe('operator actions - cancel order (UC-ORD-05)', () => {
  it('allows cancelling any order that is not finished', () => {
    for (const status of ['placed', 'accepted', 'preparing', 'ready', 'picked_up'] as const) {
      assert.equal(canOperatorCancel(status), true, status);
    }
  });

  it('does not allow cancelling delivered, cancelled or rejected orders', () => {
    for (const status of ['delivered', 'cancelled', 'rejected'] as const) {
      assert.equal(canOperatorCancel(status), false, status);
    }
  });

  it('marks only the chosen order as cancelled without changing the original list', () => {
    const before = ordersMock.map((o) => ({ ...o }));
    const target = ordersMock.find((o) => canOperatorCancel(o.status))!;
    const after = markOrderCancelled(ordersMock, target.id);
    assert.equal(after.find((o) => o.id === target.id)!.status, 'cancelled');
    assert.equal(after.filter((o) => o.status === 'cancelled').length,
      before.filter((o) => o.status === 'cancelled').length + 1);
    assert.deepEqual(ordersMock, before);
  });
});

describe('operator actions - restaurant status (UC-ORD-06)', () => {
  it('offers only statuses different from the current one', () => {
    assert.deepEqual(availableStatusChanges('open'), ['paused', 'closed']);
    assert.deepEqual(availableStatusChanges('paused'), ['open', 'closed']);
    assert.deepEqual(availableStatusChanges('closed'), ['open', 'paused']);
  });

  it('changes only the chosen restaurant', () => {
    const first = restaurantsMock[0];
    const after = applyRestaurantStatus(restaurantsMock, first.id, 'closed');
    assert.equal(after[0].status, 'closed');
    assert.deepEqual(after.slice(1), restaurantsMock.slice(1));
    assert.equal(restaurantsMock[0].status, first.status);
  });
});

describe('operator profile (UC-REG-03)', () => {
  const current = { id: 8, name: 'Olivia', email: 'o@demo.test', phone: '+15145550108', role: 'operator' as const };

  it('sends only the fields that changed', () => {
    assert.deepEqual(validateProfileUpdate({ phone: '5145550199', password: '' }, current),
      { ok: true, request: { phone: '5145550199' } });
    assert.deepEqual(validateProfileUpdate({ phone: '', password: 'newpassword1' }, current),
      { ok: true, request: { password: 'newpassword1' } });
  });

  it('accepts a phone with spaces, dashes and a plus sign', () => {
    const result = validateProfileUpdate({ phone: '+1 (514) 555-0199', password: '' }, current);
    assert.equal(result.ok, true);
  });

  it('rejects an invalid phone number', () => {
    const result = validateProfileUpdate({ phone: '12ab', password: '' }, current);
    assert.ok(!result.ok);
    assert.ok(result.errors.phone);
  });

  it('rejects passwords shorter than 8 or longer than 72 characters', () => {
    assert.ok(!validateProfileUpdate({ phone: '', password: 'short' }, current).ok);
    assert.ok(!validateProfileUpdate({ phone: '', password: 'x'.repeat(73) }, current).ok);
    assert.ok(validateProfileUpdate({ phone: '', password: 'x'.repeat(72) }, current).ok);
  });

  it('asks for a change when nothing changed', () => {
    const same = validateProfileUpdate({ phone: current.phone, password: '' }, current);
    assert.ok(!same.ok);
    assert.ok(same.errors.form);
    assert.ok(!validateProfileUpdate({ phone: '', password: '' }, current).ok);
  });

  it('reports every problem at once', () => {
    const result = validateProfileUpdate({ phone: 'abc', password: 'x' }, current);
    assert.ok(!result.ok);
    assert.ok(result.errors.phone && result.errors.password);
  });

  it('never lets the role change: the response is always shown as operator', () => {
    const user = profileFromResponse({ id: 8, name: 'Olivia', email: 'o@demo.test', phone: '5145550199', role: 'CUSTOMER' });
    assert.equal(user.role, 'operator');
    assert.equal(user.phone, '5145550199');
  });
});